            launch.stderr_handle.close()  # type: ignore[attr-defined]
        if not Path(f"{launch.output}.done").is_file():
            _ = Path(f"{launch.output}.done").write_text(f"{rc}\n", encoding="utf-8")
        if launch in _ACTIVE_LAUNCHES:
            _ACTIVE_LAUNCHES.remove(launch)
        if launch in _DISPATCH_LAUNCHES:
            _DISPATCH_LAUNCHES.remove(launch)


def _split_summary_blocks(stdout: str) -> list[str]:
    blocks: list[str] = []
    current: list[str] = []
    for line in stdout.splitlines():
        if not line:
            if current:
                blocks.append("\n".join(current))
                current = []
        else:
            current.append(line)
    if current:
        blocks.append("\n".join(current))
    return blocks


def _parse_block(block: str) -> tuple[str, str]:
    status = ""
    reviewer_file = ""
    for line in block.splitlines():
        key, sep, value = line.partition("=")
        if not sep:
            continue
        if key == "STATUS":
            status = value
        elif key == "REVIEWER_FILE":
            reviewer_file = value
    return status, reviewer_file


def _snippet_from_file(path: str) -> str:
    try:
        with Path(path).open("rb") as handle:
            data = handle.read(2000)
    except OSError:
        return ""
    text = data.decode("utf-8", errors="replace")
    return text.replace("\n", " ").replace("\r", " ").replace("\t", " ")[:200]


def _first_nonblank_trimmed(text: str) -> str:
    for line in text.splitlines():
        if line.strip():
            return line.strip()
    return ""


def _salvage_first_line(check_file: str, pattern: re.Pattern[str]) -> bool:
    try:
        lines = Path(check_file).read_text(encoding="utf-8", errors="replace").splitlines(keepends=True)
    except OSError:
        return False
    for idx, line in enumerate(lines):
        if pattern.search(line.rstrip("\n")):
            if idx <= 0:
                return False
            fd, tmp = tempfile.mkstemp(prefix=f"{Path(check_file).name}.salvage.", dir=str(Path(check_file).parent))
            try:
                with os.fdopen(fd, "w", encoding="utf-8") as handle:
                    handle.writelines(lines[idx:])
                _ = Path(tmp).replace(check_file)
                return True
            except OSError:
                with contextlib.suppress(OSError):
                    Path(tmp).unlink()
                return False
    return False


def _collect_phase(
    launches: Sequence[PhaseLaunch],
    opts: Options,
    final_outputs: list[str],
    final_tools: list[str],
    drops: list[DropState],
    result_pattern: re.Pattern[str] | None,
    first_line_pattern: re.Pattern[str] | None,
) -> list[int]:
    if not launches:
        return []
    _reap_phase(launches)
    outputs = [launch.output for launch in launches]
    result = proc.run(
        [sys.executable, str(PY_CLI), "agent", "collect-results", "--timeout", opts.timeout, "--summary-only", *outputs]
    )
    blocks = _split_summary_blocks(result.stdout if result.returncode == 0 else "")
    failed: list[int] = []
    for pos, launch in enumerate(launches):
        idx = launch.idx
        output = launch.output
        status, reviewer_file = _parse_block(blocks[pos] if pos < len(blocks) else "")
        if status in {"OK", "cap_hit"}:

        if status in {"OK", "cap_hit"}:
            if status == "OK" and result_pattern is not None:
                check_file = reviewer_file or output
                if not Path(check_file).is_file():
                    _err(
                        "dispatch-with-waterfall.sh: result file not readable for --require-result-pattern check: "
                        f"{check_file}"
                    )
                    drops[idx] = DropState("result-unreadable", f"result file not readable: {check_file}")
                    failed.append(idx)
                    continue
                content = Path(check_file).read_text(encoding="utf-8", errors="replace")
                if not result_pattern.search(content):
                    drops[idx] = DropState("result-gate-miss", _snippet_from_file(check_file))
                    failed.append(idx)
                    continue
            if status == "OK" and first_line_pattern is not None:
                check_file = reviewer_file or output
                if not Path(check_file).is_file():
                    _err(
                        "dispatch-with-waterfall.sh: result file not readable for --require-first-line-pattern check: "
                        f"{check_file}"
                    )
                    drops[idx] = DropState("result-unreadable", f"result file not readable: {check_file}")
                    failed.append(idx)
                    continue
                content = Path(check_file).read_text(encoding="utf-8", errors="replace")
                first_nonblank = _first_nonblank_trimmed(content)
                if not first_line_pattern.search(first_nonblank):
                    if not first_nonblank:
                        drops[idx] = DropState("empty", "")
                        failed.append(idx)
                        continue
                    if not _salvage_first_line(check_file, first_line_pattern):
                        drops[idx] = DropState("format-gate-miss", _snippet_from_file(check_file))
                        failed.append(idx)
                        continue
            final_outputs[idx] = reviewer_file or output
            final_tools[idx] = launch.tool
            drops[idx] = DropState()
        else:
            stderr_snippet = _snippet_from_file(f"{output}.launch-stderr")
            detail = f"STATUS={status or 'unknown'}"
            if stderr_snippet:
                detail = f"{detail} {stderr_snippet}"
            drops[idx] = DropState("collector-failure", detail)
            failed.append(idx)
    return failed


def _write_counter(path: str, combined_fallback: int) -> None:
    if not path:
        return
    prior = 0
    try:
        raw = Path(path).read_text(encoding="utf-8", errors="replace").strip()
        if raw.isdigit():
            prior = int(raw, 10)
    except OSError:
        pass
    fd, tmp = tempfile.mkstemp(prefix=f"{Path(path).name}.tmp.", dir=str(Path(path).parent))
    with os.fdopen(fd, "w", encoding="utf-8") as handle:
        _ = handle.write(f"{prior + combined_fallback}\n")
    _ = Path(tmp).replace(path)


def _flatten_field(text: str) -> str:
    return text.replace("\t", " ").replace("\n", " ").replace("\r", " ")


def _write_drops(path: str, slots: Sequence[Slot], final_outputs: Sequence[str], drops: Sequence[DropState]) -> str:
    paths_dir = Path(path).parent
    tmp = ""
    try:
        fd, tmp = tempfile.mkstemp(prefix=".dispatch-waterfall-drops.", dir=str(paths_dir))
        drop_any = False
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            for idx, slot in enumerate(slots):
                if final_outputs[idx]:
                    continue
                drop_any = True
                _ = handle.write(
                    f"{_flatten_field(slot.name)}\t{_flatten_field(slot.tool)}\t{drops[idx].reason or 'unknown'}\t{drops[idx].detail}\n"
                )
        if not drop_any:
            Path(tmp).unlink(missing_ok=True)
            return ""
        dropped_slots_file = f"{path}.dropped-slots"
        _ = Path(tmp).replace(dropped_slots_file)
        return dropped_slots_file
    except OSError as exc:
        if tmp:
            with contextlib.suppress(OSError):
                Path(tmp).unlink()
        raise ValidationError(f"dispatch-with-waterfall.sh: dropped-slots sidecar not writable: {path}") from exc


def _write_paths_file(path: str, final_outputs: Sequence[str], *, no_fallback: bool) -> None:
    paths_dir = Path(path).parent
    tmp = ""
    try:
        fd, tmp = tempfile.mkstemp(prefix=".dispatch-waterfall-paths.", dir=str(paths_dir))
        with os.fdopen(fd, "w", encoding="utf-8") as handle:
            for output in final_outputs:
                if no_fallback and not output:
                    continue
                _ = handle.write(f"{output}\n")
        _ = Path(tmp).replace(path)
    except OSError as exc:
        if tmp:
            with contextlib.suppress(OSError):
                Path(tmp).unlink()
        raise ValidationError(f"dispatch-with-waterfall.sh: paths-file not writable: {path}") from exc


def _emit_bool(key: str, *, value: bool) -> None:
    logging_util.emit_kv(key, "true" if value else "false")

#!/usr/bin/env bash
# write-implement-round-meta.sh — synthesize /implement code-review round
# renderer metadata (round-meta.json) from available new-format artifacts.
#
# Analogous to write-design-round-meta.sh but adapted for /implement rounds,
# which carry findings-classification.tsv + voting-tally.md + panel-manifest.ndjson
# instead of the old-format sidecar files. Called from review-and-fix CLI before
# flush_round_log_after_coder so the file is present when write-round copies it
# to the larch-log directory (round-meta.json is included in _ROUND_ARTIFACT_ALLOW
# in python/run_logs.py).
#
# render-review-phase-detail.sh gates each round on the presence of round-meta.json
# (line 80); without it the Review Phase Detail table is never emitted in the
# final report (issue #4038).

set -euo pipefail

usage() {
    printf '%s\n' 'Usage: write-implement-round-meta.sh --round-dir DIR' >&2
}

ROUND_DIR=""
while [ $# -gt 0 ]; do
    case "$1" in
        --round-dir) [ $# -ge 2 ] || { usage; exit 2; }; ROUND_DIR="$2"; shift 2 ;;
        -h|--help) usage; exit 0 ;;
        *) usage; exit 2 ;;
    esac
done

[ -n "$ROUND_DIR" ] || { usage; exit 2; }
[ -d "$ROUND_DIR" ] || exit 0

ACCEPTED_COUNT=0
REJECTED_COUNT=0
NEUTRAL_COUNT=0
EXONERATED_COUNT=0
OOS_ACCEPTED_COUNT=0
OOS_REJECTED_COUNT=0

_parse_tally_md() {
    local file="$1"
    awk -F'|' '
        function trim(s) { gsub(/^[[:space:]]+|[[:space:]]+$/, "", s); return s }
        /^## Findings/ { in_findings=1; next }
        /^## / && in_findings { in_findings=0 }
        in_findings && NF >= 4 {
            item=trim($2)
            result=trim($(NF-1))
            if (result == "" || result ~ /^-+$/) {
                result=trim($(NF-2))
            }
            if (item == "" || item == "Item" || item ~ /^-+$/ || result == "" || result == "Result" || result ~ /^-+$/) {
                next
            }
            if (item ~ /^FINDING_[0-9A-Za-z_]+$/) {
                if (result == "accepted") accepted++
                else if (result == "rejected") rejected++
                else if (result == "neutral") neutral++
                else if (result == "exonerated") exonerated++
            } else if (item ~ /^OOS_[0-9A-Za-z_]+$/) {
                if (result == "accepted") oos_accepted++
                else oos_rejected++
            }
        }
        END { printf "%d\t%d\t%d\t%d\t%d\t%d\n", accepted+0, rejected+0, neutral+0, exonerated+0, oos_accepted+0, oos_rejected+0 }
    ' "$file" 2>/dev/null || printf '0\t0\t0\t0\t0\t0\n'
}

_parse_classification_tsv() {
    local file="$1"
    awk -F'\t' '
        NR == 1 { next }
        function trim(s) { gsub(/^[[:space:]]+|[[:space:]]+$/, "", s); return s }
        {
            item=trim($1)
            result=trim($3)
            if (item == "" || result == "") next
            if (item ~ /^FINDING_[0-9A-Za-z_]+$/) {
                if (result == "accepted") accepted++
                else if (result == "rejected") rejected++
                else if (result == "neutral") neutral++
                else if (result == "exonerated") exonerated++
            } else if (item ~ /^OOS_[0-9A-Za-z_]+$/) {
                if (result == "accepted") oos_accepted++
                else oos_rejected++
            }
        }
        END { printf "%d\t%d\t%d\t%d\t%d\t%d\n", accepted+0, rejected+0, neutral+0, exonerated+0, oos_accepted+0, oos_rejected+0 }
    ' "$file" 2>/dev/null || printf '0\t0\t0\t0\t0\t0\n'
}

_counts_all_zero() {
    [ "${1:-}" = "$(printf '0\t0\t0\t0\t0\t0')" ]
}

_tsv_has_data_rows() {
    local file="$1"
    awk 'NR > 1 && NF > 0 { found = 1; exit } END { exit(found ? 0 : 1) }' "$file" 2>/dev/null
}

_counts=""
_count_source=""
_md_counts=""
_tsv_counts=""
if [ -f "$ROUND_DIR/voting-tally.md" ]; then
    _md_counts="$(_parse_tally_md "$ROUND_DIR/voting-tally.md")"
    _counts="$_md_counts"
    _count_source=md
fi
if [ -f "$ROUND_DIR/findings-classification.tsv" ]; then
    _tsv_counts="$(_parse_classification_tsv "$ROUND_DIR/findings-classification.tsv")"
    if [ -z "$_counts" ]; then
        _counts="$_tsv_counts"
        _count_source=tsv
    elif _counts_all_zero "$_md_counts" && _tsv_has_data_rows "$ROUND_DIR/findings-classification.tsv"; then
        _counts="$_tsv_counts"
        _count_source=tsv
    fi
fi
[ -n "$_counts" ] || _counts=$(printf '0\t0\t0\t0\t0\t0')

IFS=$'\t' read -r ACCEPTED_COUNT REJECTED_COUNT NEUTRAL_COUNT EXONERATED_COUNT OOS_ACCEPTED_COUNT OOS_REJECTED_COUNT <<EOF_COUNTS
$_counts
EOF_COUNTS
for _v in ACCEPTED_COUNT REJECTED_COUNT NEUTRAL_COUNT EXONERATED_COUNT OOS_ACCEPTED_COUNT OOS_REJECTED_COUNT; do
    case "${!_v:-}" in ''|*[!0-9]*) printf -v "$_v" '%s' 0 ;; esac
done

_panel_count=0
if [ -f "$ROUND_DIR/panel-manifest.ndjson" ] && command -v python3 >/dev/null 2>&1; then
    _panel_count=$(python3 - "$ROUND_DIR/panel-manifest.ndjson" <<'PY' || printf '0'
import json
import sys
count = 0
try:
    with open(sys.argv[1], encoding='utf-8', errors='replace') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except Exception:
                continue
            if isinstance(obj, dict) and any(obj.get(k) for k in ('slot', 'tool', 'output')):
                count += 1
except OSError:
    pass
print(count)
